import math

def f(n):
    """Calculates the largest odd divisor of n."""
    if n <= 0:
        raise ValueError("Input must be a positive integer.")
    while n % 2 == 0:
        n //= 2
    return n

def check_condition(u, v):
    """Checks if the condition holds for a given u and v."""
    if u <= 0 or v <= 0:
        return False

    # We need to check v consecutive differences starting from j=0 up to j=v-1
    for j in range(v):
        term1 = f(u + v + j) - f(u + j)
        if term1 % 4 != 0:
            return False
    return True

def search_solutions(v_values, max_u=100):
    """Searches for solutions u <= max_u for the given v values."""
    results = {}
    for v in v_values:
        solutions_u = []
        for u in range(1, max_u + 1):
            if check_condition(u, v):
                solutions_u.append(u)
        results[v] = solutions_u
    return results

